"use strict";var objChart={},choiceContainer=undefined,datasets={};(function(){function n(){var n=[];choiceContainer.find("input:checked").each(function(){var t=$(this).attr("name");t&&datasets[t]&&n.push(datasets[t])});n.length>0&&$.plot($("#placeholder"),n,{yaxis:{min:0},xaxis:{tickDecimals:0}})}datasets={Low:{label:"Low",data:[]},High:{label:"High",data:[]},Open:{label:"Open",data:[]},Close:{label:"Close",data:[]}};$(document).ready(function(){var n=0;$.each(datasets,function(t,i){i.color=n;++n});choiceContainer=$("#choices");$.each(datasets,function(n,t){choiceContainer.append('<input type="checkbox" name="'+n+'" checked="checked" id="id'+n+'"><label for="id'+n+'">'+t.label+"<\/label>")})});objChart.SetChart=function(){choiceContainer.find("input").click(n);setTimeout(function(){n()},1e3);alert(JSON.stringify(datasets))}})(objChart);